#!/usr/bin/env python3
"""Post-processing for 72B zero-shot NER: 5-signal evaluation + entity construction."""

import json
import os
import sys
import statistics
from collections import Counter, defaultdict

import numpy as np
from scipy.stats import spearmanr, kendalltau, rankdata

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from consistency import compute_all_consistency_scores
from evaluation import per_instance_f1

BASE = "/root/autodl-tmp/struct_self_consist_ie"
OUTPUT_BASE = f"{BASE}/output/72b_zeroshot"

DATASETS = {
    "scierc": f"{OUTPUT_BASE}/scierc/samples.jsonl",
    "conll2003": f"{OUTPUT_BASE}/conll2003/samples.jsonl",
    "fewnerd": f"{OUTPUT_BASE}/fewnerd/samples.jsonl",
}

SUBTASK = "ner"


def load_data(path, gold_filter=True):
    instances = []
    with open(path) as f:
        for line in f:
            if not line.strip():
                continue
            obj = json.loads(line)
            if gold_filter and len(obj["gold"].get("entities", [])) == 0:
                continue
            instances.append(obj)
    return instances


def compute_entity_f1(pred_entities, gold_entities):
    pred = {(e["start"], e["end"], e["type"]) for e in pred_entities}
    gold = {(e["start"], e["end"], e["type"]) for e in gold_entities}
    if not gold and not pred:
        return 1.0
    if not gold or not pred:
        return 0.0
    tp = len(pred & gold)
    if tp == 0:
        return 0.0
    p = tp / len(pred)
    r = tp / len(gold)
    return 2 * p * r / (p + r)


def compute_exact_match_rate(samples):
    keys = [frozenset((e["text"], e["type"]) for e in s.get("entities", [])) for s in samples]
    if not keys:
        return 0.0
    counter = Counter(keys)
    return counter.most_common(1)[0][1] / len(samples)


def compute_voting_confidence(samples):
    N = len(samples)
    if N == 0:
        return 0.0
    counter = Counter()
    for s in samples:
        for e in s.get("entities", []):
            counter[(e["text"], e["type"])] += 1
    if not counter:
        return 0.0
    return float(np.mean([v / N for v in counter.values()]))


def compute_mean_logprob(samples, inst):
    lps = []
    for i, s in enumerate(samples):
        if "mean_logprob" in s:
            lps.append(s["mean_logprob"])
        elif "logprobs" in inst and i < len(inst["logprobs"]):
            lps.append(inst["logprobs"][i])
    lps = [lp for lp in lps if np.isfinite(lp)]
    return float(np.mean(lps)) if lps else float("nan")


def safe_auroc(scores, labels):
    scores = np.asarray(scores, dtype=float)
    labels = np.asarray(labels, dtype=int)
    if len(np.unique(labels)) < 2:
        return float("nan")
    n_pos = np.sum(labels == 1)
    n_neg = np.sum(labels == 0)
    if n_pos == 0 or n_neg == 0:
        return float("nan")
    ranks = rankdata(scores)
    u = ranks[labels == 1].sum() - n_pos * (n_pos + 1) / 2
    return float(u / (n_pos * n_neg))


def safe_spearman(x, y):
    x, y = np.asarray(x, dtype=float), np.asarray(y, dtype=float)
    mask = np.isfinite(x) & np.isfinite(y)
    x, y = x[mask], y[mask]
    if len(x) < 3:
        return float("nan")
    return float(spearmanr(x, y).statistic)


def bootstrap_ci(values, n_boot=2000, seed=42):
    rng = np.random.RandomState(seed)
    arr = np.array(values)
    n = len(arr)
    if n == 0:
        return {"mean": 0.0, "ci_lo": 0.0, "ci_hi": 0.0}
    boot_means = np.array([arr[rng.randint(0, n, n)].mean() for _ in range(n_boot)])
    boot_means.sort()
    return {
        "mean": float(arr.mean()),
        "ci_lo": float(boot_means[int(0.025 * n_boot)]),
        "ci_hi": float(boot_means[int(0.975 * n_boot)]),
    }


def consensus_construct(inst, high_thresh=0.7, medium_thresh=0.3):
    """Entity construction with LP-weighted decisions."""
    samples = inst["samples"]
    N = len(samples)

    entity_counts = Counter()
    entity_sample_indices = defaultdict(list)

    for i, s in enumerate(samples):
        seen = set()
        for e in s.get("entities", []):
            key = (e["start"], e["end"], e["type"])
            if key not in seen:
                entity_counts[key] += 1
                entity_sample_indices[key].append(i)
                seen.add(key)

    sample_lps = []
    for i, s in enumerate(samples):
        lp = s.get("mean_logprob")
        if lp is None and "logprobs" in inst and i < len(inst["logprobs"]):
            lp = inst["logprobs"][i]
        if lp is not None:
            sample_lps.append(lp)
    instance_median_lp = statistics.median(sample_lps) if sample_lps else 0.0

    consensus = []
    for entity_key, count in entity_counts.items():
        freq = count / N
        if freq > high_thresh:
            consensus.append(entity_key)
        elif freq > medium_thresh:
            contributing_lps = []
            for i in entity_sample_indices[entity_key]:
                lp = samples[i].get("mean_logprob")
                if lp is None and "logprobs" in inst and i < len(inst["logprobs"]):
                    lp = inst["logprobs"][i]
                if lp is not None:
                    contributing_lps.append(lp)
            if contributing_lps:
                mean_lp = statistics.mean(contributing_lps)
                if mean_lp > instance_median_lp:
                    consensus.append(entity_key)

    return [{"start": s, "end": e, "type": t} for s, e, t in consensus]


def majority_vote_span(inst, threshold=0.5):
    samples = inst["samples"]
    N = len(samples)
    entity_counts = Counter()
    for s in samples:
        seen = set()
        for e in s.get("entities", []):
            key = (e["start"], e["end"], e["type"])
            if key not in seen:
                entity_counts[key] += 1
                seen.add(key)
    return [{"start": k[0], "end": k[1], "type": k[2]}
            for k, c in entity_counts.items() if c / N > threshold]


def evaluate_dataset(name, path):
    print(f"\n{'='*60}")
    print(f"  {name}")
    print(f"{'='*60}")

    instances = load_data(path, gold_filter=True)
    print(f"  Loaded {len(instances)} instances (gold-filtered)")
    if not instances:
        return None

    N_samples = len(instances[0]["samples"])

    # 5 signals
    consistency = compute_all_consistency_scores(instances, subtask=SUBTASK)
    sj_vals = consistency["soft_jaccard"]
    fk_vals = consistency["fleiss_kappa"]

    lp_vals, em_vals, vc_vals, f1_vals = [], [], [], []
    for inst in instances:
        samples = inst["samples"]
        gold = inst["gold"]
        greedy = inst.get("greedy", samples[0])
        lp_vals.append(compute_mean_logprob(samples, inst))
        em_vals.append(compute_exact_match_rate(samples))
        vc_vals.append(compute_voting_confidence(samples))
        f1_vals.append(per_instance_f1(greedy, gold, subtask=SUBTASK))

    signals = {
        "SJ": np.array(sj_vals, dtype=float),
        "FK": np.array(fk_vals, dtype=float),
        "LP": np.array(lp_vals, dtype=float),
        "EM": np.array(em_vals, dtype=float),
        "VC": np.array(vc_vals, dtype=float),
    }
    f1_arr = np.array(f1_vals, dtype=float)

    # Signal correlations
    signal_results = {}
    for sig_name, sig_vals in signals.items():
        rho = safe_spearman(sig_vals, f1_arr)
        signal_results[sig_name] = {"rho": rho}

    # Baselines
    greedy_f1s = f1_vals
    oracle_f1s = []
    lp_selection_f1s = []
    for inst in instances:
        gold_ents = inst["gold"]["entities"]
        sample_f1s = [compute_entity_f1(s.get("entities", []), gold_ents)
                      for s in inst["samples"]]
        oracle_f1s.append(max(sample_f1s))

        best_lp_idx = 0
        best_lp = float("-inf")
        for i, s in enumerate(inst["samples"]):
            lp = s.get("mean_logprob")
            if lp is None and "logprobs" in inst and i < len(inst["logprobs"]):
                lp = inst["logprobs"][i]
            if lp is not None and lp > best_lp:
                best_lp = lp
                best_lp_idx = i
        lp_selection_f1s.append(compute_entity_f1(
            inst["samples"][best_lp_idx].get("entities", []), gold_ents))

    mv_f1s = [compute_entity_f1(majority_vote_span(inst), inst["gold"]["entities"])
              for inst in instances]

    # theta=2/N consensus
    theta = 2 / N_samples
    consensus_2n_f1s = [compute_entity_f1(
        consensus_construct(inst, high_thresh=theta, medium_thresh=0.0),
        inst["gold"]["entities"]) for inst in instances]

    # LP-weighted consensus (high=0.5, medium=2/N)
    consensus_lp_f1s = [compute_entity_f1(
        consensus_construct(inst, high_thresh=0.5, medium_thresh=theta),
        inst["gold"]["entities"]) for inst in instances]

    # Multiple threshold configs
    thresholds = [
        {"high": 0.5, "medium": 0.1},
        {"high": 0.6, "medium": 0.2},
        {"high": 0.7, "medium": 0.3},
    ]
    consensus_variants = {}
    for cfg in thresholds:
        key = f"high={cfg['high']}_medium={cfg['medium']}"
        cc_f1s = [compute_entity_f1(
            consensus_construct(inst, high_thresh=cfg["high"], medium_thresh=cfg["medium"]),
            inst["gold"]["entities"]) for inst in instances]
        consensus_variants[key] = bootstrap_ci(cc_f1s)

    result = {
        "name": name,
        "n_instances": len(instances),
        "n_samples": N_samples,
        "signals": signal_results,
        "baselines": {
            "greedy": bootstrap_ci(greedy_f1s),
            "lp_selection": bootstrap_ci(lp_selection_f1s),
            "majority_vote": bootstrap_ci(mv_f1s),
            "oracle": bootstrap_ci(oracle_f1s),
            "consensus_theta2n": bootstrap_ci(consensus_2n_f1s),
            "consensus_lp_weighted": bootstrap_ci(consensus_lp_f1s),
        },
        "consensus_variants": consensus_variants,
    }

    # Print summary
    print(f"  N={N_samples}")
    print(f"\n  Signal correlations (Spearman rho vs greedy F1):")
    for sig, v in signal_results.items():
        print(f"    {sig:4s}: rho={v['rho']:.4f}")

    print(f"\n  Entity F1 (mean [95% CI]):")
    for label, key in [("Greedy", "greedy"), ("LP Selection", "lp_selection"),
                       ("Majority Vote", "majority_vote"),
                       ("Consensus theta=2/N", "consensus_theta2n"),
                       ("Consensus LP-wt", "consensus_lp_weighted"),
                       ("Oracle", "oracle")]:
        ci = result["baselines"][key]
        print(f"    {label:25s} {ci['mean']:.4f}  [{ci['ci_lo']:.4f}, {ci['ci_hi']:.4f}]")

    return result


def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--datasets", nargs="+", default=list(DATASETS.keys()))
    args = parser.parse_args()

    all_results = {}
    for ds_name in args.datasets:
        path = DATASETS.get(ds_name)
        if not path or not os.path.exists(path):
            print(f"Skipping {ds_name}: file not found at {path}")
            continue
        result = evaluate_dataset(ds_name, path)
        if result:
            all_results[ds_name] = result

    # Save combined report
    report_path = f"{OUTPUT_BASE}/full_signal_report.json"
    os.makedirs(os.path.dirname(report_path), exist_ok=True)
    with open(report_path, "w") as f:
        json.dump(all_results, f, indent=2, default=str)
    print(f"\nReport saved to {report_path}")


if __name__ == "__main__":
    main()
